/**
 * Ricava tempo/gittata/note di un incantesimo dalla sua descrizione (le meccaniche
 * sono nel testo di SPIEG_INCANTESIMI). Restituisce null se non c'è descrizione,
 * così chi chiama può decidere se lasciare i valori esistenti o usare un default.
 */

/** Righe (di un testo libero) che hanno una spiegazione, come lista cliccabile ⓘ. */
function renderSpiegazioni(testo, lookup, setInfo) {
  const trovate = String(testo || '')
    .split('\n').map((r) => r.trim()).filter(Boolean)
    .map((r) => ({ r, sp: lookup(r) })).filter((x) => x.sp);
  if (trovate.length === 0) return null;
  return (
    <div style={{ marginTop: 8, fontSize: 12, borderTop: `1px solid ${C.border}`, paddingTop: 6 }}>
      <div style={{ ...styles.detail, marginBottom: 3 }}>{tr('ⓘ Tocca per la spiegazione:', 'ⓘ Tap for the explanation:')}</div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
        {trovate.map(({ r, sp }, i) => (
          <span role="button" tabIndex={0}
            key={i}
            style={{ cursor: 'help', background: 'rgba(0,0,0,0.04)', border: `1px solid ${C.border}`, borderRadius: 6, padding: '2px 7px' }}
            onClick={() => setInfo({ titolo: r, testo: sp })}
          >{r} ⓘ</span>
        ))}
      </div>
    </div>
  );
}

/** Badge che mostra l'effetto dello Sfinimento su un valore della scheda
 * (Velocità o PF Massimi), sullo stesso modello di BadgePotere. */
function BadgeSfinimento({ scheda, bersaglio }) {
  const eff = effettiSfinimento(scheda);
  if (!eff.livello) return null;
  if (bersaglio === 'velocita') {
    if (eff.velocitaZero) {
      return <span style={{ fontSize: 11, fontWeight: 700, color: C.red, marginLeft: 4 }} title="Sfinimento: velocità ridotta a 0">→0 (Sfin.)</span>;
    }
    if (eff.velocitaDimezzata) {
      return <span style={{ fontSize: 11, fontWeight: 700, color: C.red, marginLeft: 4 }} title="Sfinimento: velocità dimezzata">½ (Sfin.)</span>;
    }
    if (eff.penalitaVelocita) {
      return <span style={{ fontSize: 11, fontWeight: 700, color: C.red, marginLeft: 4 }} title="Sfinimento: -1,5m per livello">−{eff.penalitaVelocita}m (Sfin.)</span>;
    }
    return null;
  }
  if (bersaglio === 'pf_massimi' && eff.pfDimezzati) {
    return <span style={{ fontSize: 11, fontWeight: 700, color: C.red, marginLeft: 4 }} title="Sfinimento: PF massimi dimezzati">½ (Sfin.)</span>;
  }
  return null;
}

